<?php require_once __DIR__.'/../bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];if(isset($_POST['delete']))$pdo->prepare('DELETE FROM anime WHERE id=?')->execute([$id]);else{$s=$pdo->prepare('UPDATE anime SET title=?,english_title=?,synopsis=?,type=?,status=?,year=?,score=? WHERE id=?');$s->execute([trim($_POST['title']),trim($_POST['english_title']),trim($_POST['synopsis']),trim($_POST['type']),trim($_POST['status']),($_POST['year']?:null),($_POST['score']?:null),$id]);}header('Location: anime.php');exit;}$term=trim($_GET['q']??'');$page=valid_page();$per=25;$where=$term?'WHERE title LIKE ?':'';$count=$pdo->prepare("SELECT COUNT(*) FROM anime $where");$count->execute($term?["%$term%"]:[]);$pages=max(1,(int)ceil($count->fetchColumn()/$per));$s=$pdo->prepare("SELECT id,title,type,year,score FROM anime $where ORDER BY title LIMIT ? OFFSET ?");if($term)$s->bindValue(1,"%$term%");$n=$term?2:1;$s->bindValue($n,$per,PDO::PARAM_INT);$s->bindValue($n+1,($page-1)*$per,PDO::PARAM_INT);$s->execute();$title='Manage anime — AniRead';include __DIR__.'/../includes/header.php';?><h1>Manage anime</h1><form class="filters"><input class="input" name="q" value="<?=e($term)?>" placeholder="Search anime"><button class="btn">Search</button></form><table class="table"><tr><th>Title</th><th>Type</th><th>Year</th><th>Score</th><th>Actions</th></tr><?php foreach($s as $a):?><tr><td><?=e($a['title'])?></td><td><?=e($a['type'])?></td><td><?=e($a['year'])?></td><td><?=e($a['score'])?></td><td><a class="btn alt" href="anime-edit.php?id=<?=$a['id']?>">Edit</a> <form style="display:inline" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$a['id']?>"><button class="btn alt" name="delete" data-confirm="Delete this anime and its episodes?">Delete</button></form></td></tr><?php endforeach;?></table><?php page_links($page,$pages,'anime.php?q='.rawurlencode($term));include __DIR__.'/../includes/footer.php';
